'use client'

import { useId, useState, type FormEvent, type HTMLAttributes } from 'react'
import { ArrowRight, CheckCircle2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'

export interface NewsletterFormProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onSubmit'> {
  title?: string
  description?: string
  placeholder?: string
  submitLabel?: string
  successMessage?: string
  errorMessage?: string
  variant?: 'inline' | 'card'
  consentLabel?: string
  onSubmit: (email: string) => Promise<void> | void
}

export function NewsletterForm({
  title = 'Receba nossas novidades',
  description,
  placeholder = 'voce@empresa.com',
  submitLabel = 'Inscrever-se',
  successMessage = 'Inscrição realizada com sucesso.',
  errorMessage = 'Não foi possível concluir a inscrição.',
  variant = 'card',
  consentLabel,
  onSubmit,
  className,
  ...props
}: NewsletterFormProps) {
  const id = useId()
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle')

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = event.currentTarget
    const email = String(new FormData(form).get('email') ?? '')
    setStatus('loading')
    try {
      await onSubmit(email)
      setStatus('success')
      form.reset()
    } catch {
      setStatus('error')
    }
  }

  return (
    <div
      className={cn(
        variant === 'card' && 'rounded-2xl border bg-card p-6 shadow-sm md:p-8',
        className,
      )}
      {...props}
    >
      {title ? <h2 className="text-2xl font-bold tracking-tight">{title}</h2> : null}
      {description ? <p className="mt-2 text-muted-foreground">{description}</p> : null}
      <form className="mt-5" onSubmit={handleSubmit}>
        <label htmlFor={id} className="sr-only">
          E-mail
        </label>
        <div
          className={cn('flex gap-2', variant === 'inline' ? 'flex-col sm:flex-row' : 'flex-col')}
        >
          <Input
            id={id}
            name="email"
            type="email"
            autoComplete="email"
            required
            placeholder={placeholder}
            aria-describedby={`${id}-status`}
          />
          <Button type="submit" disabled={status === 'loading'} className="shrink-0">
            {status === 'loading' ? 'Enviando…' : submitLabel}
            {status !== 'loading' ? (
              <ArrowRight className="ml-2 h-4 w-4" aria-hidden="true" />
            ) : null}
          </Button>
        </div>
        {consentLabel ? (
          <label className="mt-3 flex items-start gap-2 text-xs text-muted-foreground">
            <input
              type="checkbox"
              required
              className="mt-0.5 h-4 w-4 rounded border-input accent-primary"
            />
            <span>{consentLabel}</span>
          </label>
        ) : null}
        <div id={`${id}-status`} aria-live="polite" className="mt-3 min-h-5 text-sm">
          {status === 'success' ? (
            <p className="flex items-center gap-2 text-emerald-600">
              <CheckCircle2 className="h-4 w-4" />
              {successMessage}
            </p>
          ) : null}
          {status === 'error' ? <p className="text-destructive">{errorMessage}</p> : null}
        </div>
      </form>
    </div>
  )
}

export { HeroCarousel as BannerCarousel } from './HeroCarousel'
export type {
  HeroCarouselProps as BannerCarouselProps,
  HeroCarouselSlide as BannerCarouselSlide,
} from './HeroCarousel'

'use client'

import Image from 'next/image'
import Link from 'next/link'
import { Pause, Play } from 'lucide-react'
import { useState } from 'react'
import { A11y, Autoplay, Keyboard, Navigation, Pagination } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'
import type { Swiper as SwiperInstance } from 'swiper'
import { Button } from '@/components/ui/button'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'

export type HeroCarouselSlide = {
  id: string
  title: string
  description?: string
  image: { src: string; alt: string }
  action?: { label: string; href: string }
}

export type HeroCarouselProps = {
  slides: HeroCarouselSlide[]
  autoplayDelay?: number | false
  className?: string
  label?: string
}

export function HeroCarousel({
  slides,
  autoplayDelay = 6000,
  className,
  label = 'Destaques',
}: HeroCarouselProps) {
  const reducedMotion = useReducedMotion()
  const [swiper, setSwiper] = useState<SwiperInstance | null>(null)
  const [paused, setPaused] = useState(false)
  const canAutoplay = Boolean(autoplayDelay) && !reducedMotion

  function toggleAutoplay() {
    if (!swiper) return
    if (paused) swiper.autoplay.start()
    else swiper.autoplay.stop()
    setPaused((current) => !current)
  }

  return (
    <section className={cn('relative bg-slate-950 text-white', className)} aria-label={label}>
      <Swiper
        modules={[A11y, Autoplay, Keyboard, Navigation, Pagination]}
        navigation
        pagination={{ clickable: true }}
        keyboard={{ enabled: true }}
        autoplay={
          canAutoplay
            ? { delay: Number(autoplayDelay), disableOnInteraction: true, pauseOnMouseEnter: true }
            : false
        }
        loop={slides.length > 1}
        a11y={{ enabled: true }}
        onSwiper={setSwiper}
        className="min-h-[560px]"
      >
        {slides.map((slide, index) => (
          <SwiperSlide key={slide.id}>
            <article className="relative flex min-h-[560px] items-center">
              <Image
                src={slide.image.src}
                alt={slide.image.alt}
                fill
                priority={index === 0}
                className="object-cover opacity-50"
                sizes="100vw"
              />
              <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/45 to-transparent" />
              <div className="container relative z-10 py-20">
                <h2 className="max-w-3xl text-4xl font-bold tracking-tight sm:text-6xl">
                  {slide.title}
                </h2>
                {slide.description ? (
                  <p className="mt-5 max-w-2xl text-lg text-white/80">{slide.description}</p>
                ) : null}
                {slide.action ? (
                  <Button asChild size="lg" className="mt-8">
                    <Link href={slide.action.href}>{slide.action.label}</Link>
                  </Button>
                ) : null}
              </div>
            </article>
          </SwiperSlide>
        ))}
      </Swiper>
      {canAutoplay ? (
        <Button
          type="button"
          size="icon"
          variant="secondary"
          className="absolute bottom-5 right-5 z-20 rounded-full shadow-lg"
          onClick={toggleAutoplay}
          aria-label={paused ? 'Retomar carrossel' : 'Pausar carrossel'}
        >
          {paused ? <Play className="h-4 w-4" /> : <Pause className="h-4 w-4" />}
        </Button>
      ) : null}
    </section>
  )
}

'use client'

import { useEffect, useState } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

export function prefersReducedMotion(): boolean {
  return typeof window !== 'undefined' && window.matchMedia(QUERY).matches
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const media = window.matchMedia(QUERY)
    const update = (): void => setReduced(media.matches)

    update()
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  return reduced
}

'use client'

import { useState, type HTMLAttributes, type ReactNode } from 'react'
import { X } from 'lucide-react'
import { cn } from '@/lib/utils'

export interface AnnouncementBarProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  message: ReactNode
  action?: { label: string; href: string; external?: boolean }
  variant?: 'default' | 'accent' | 'dark'
  dismissible?: boolean
  dismissLabel?: string
  onDismiss?: () => void
}

export function AnnouncementBar({
  message,
  action,
  variant = 'default',
  dismissible = false,
  dismissLabel = 'Fechar aviso',
  onDismiss,
  className,
  ...props
}: AnnouncementBarProps) {
  const [visible, setVisible] = useState(true)

  if (!visible) return null

  return (
    <div
      role="region"
      aria-label="Aviso"
